{
  "decisions": [
    {
      "requirement_id": "ETC-101",
      "methods": [
        "Test"
      ],
      "rationale": "The behavior is verified by sending a trackside message with no start sub-conditions and observing that the OBU immediately treats the start condition as fulfilled."
    },
    {
      "requirement_id": "ETC-102",
      "methods": [
        "Test"
      ],
      "rationale": "The OBU's handling of driver acknowledgement for text display termination is verified by simulating driver input and observing the display behavior under different message configurations."
    },
    {
      "requirement_id": "ETC-103",
      "methods": [
        "Test"
      ],
      "rationale": "The requirement is verified by setting up a scenario where the end condition is already met when the start condition is fulfilled and confirming that the message is not displayed."
    },
    {
      "requirement_id": "ETC-104",
      "methods": [
        "Test"
      ],
      "rationale": "The measurement of display length based on the start location is verified by moving the OBU through a defined track section and observing the display duration relative to the start point."
    },
    {
      "requirement_id": "ETC-105",
      "methods": [
        "Test"
      ],
      "rationale": "The transmission of the driver acknowledgement report is verified by acknowledging a message and monitoring the communication channel to the RBC for the correct report content."
    },
    {
      "requirement_id": "ETC-106",
      "methods": [
        "Test"
      ],
      "rationale": "The rejection logic is verified by sending a duplicate text message identifier while the previous one is unacknowledged and observing that the new message is rejected."
    },
    {
      "requirement_id": "ETC-107",
      "methods": [
        "Test"
      ],
      "rationale": "The specific deletion rules for Mode Profiles upon receiving an infill MA are verified by simulating the reception of such a message and inspecting the resulting Mode Profile state."
    },
    {
      "requirement_id": "ETC-108",
      "methods": [
        "Test"
      ],
      "rationale": "The treatment of the Mode Profile start as a temporary EOA and the calculation of the temporary SvL are verified by driving the OBU through the profile start under various LOA conditions and observing the speed limits."
    },
    {
      "requirement_id": "ETC-109",
      "methods": [
        "Test"
      ],
      "rationale": "The replacement of stored LX information is verified by sending two LX messages with the same identity but different content and checking that the OBU uses the latest data."
    }
  ]
}

{
  "decisions": [
    {
      "requirement_id": "KDH-001",
      "methods": [
        "Test"
      ],
      "rationale": "The requirement is verified by executing the system to confirm that a phishing-resistant authentication option is available and functional at AAL2."
    },
    {
      "requirement_id": "KDH-002",
      "methods": [
        "Test"
      ],
      "rationale": "The system is run with multi-factor inputs to observe that authentication at AAL2 succeeds only when the required factors are provided."
    },
    {
      "requirement_id": "KDH-003",
      "methods": [
        "Test"
      ],
      "rationale": "The system is operated with idle and active sessions to observe that reauthentication is triggered according to the defined timeouts."
    },
    {
      "requirement_id": "KDH-004",
      "methods": [
        "Test"
      ],
      "rationale": "The account recovery process is executed to observe that a notification is sent to the representative or designee."
    },
    {
      "requirement_id": "KDH-005",
      "methods": [
        "Test"
      ],
      "rationale": "The system is triggered to send notifications to verify that they are delivered to all registered addresses except postal ones."
    },
    {
      "requirement_id": "KDH-006",
      "methods": [
        "Test"
      ],
      "rationale": "The system is run with an e-Devlet assertion that has expired to observe that the citizen's session remains valid, confirming the assertion validity time is not used to limit the session."
    },
    {
      "requirement_id": "KDH-007",
      "methods": [
        "İnceleme"
      ],
      "rationale": "The federation transaction request is inspected to verify that it contains the VBP identifier and a cryptographic nonce."
    },
    {
      "requirement_id": "KDH-008",
      "methods": [
        "Test"
      ],
      "rationale": "The system is tested with an assertion containing an incorrect audience to observe that it is rejected, ensuring replay protection."
    },
    {
      "requirement_id": "KDH-009",
      "methods": [
        "Test"
      ],
      "rationale": "The process of changing a telephone number is executed to observe that it follows the binding process and requires appropriate authentication."
    },
    {
      "requirement_id": "KDH-010",
      "methods": [
        "Test"
      ],
      "rationale": "The system is tested by binding multiple authenticators to an account to observe that the operation is permitted."
    },
    {
      "requirement_id": "KDH-011",
      "methods": [
        "Test"
      ],
      "rationale": "The binding of a new authenticator is executed under different AAL conditions to observe that the required authentication level is enforced."
    },
    {
      "requirement_id": "KDH-012",
      "methods": [
        "Test"
      ],
      "rationale": "The addition of a new authenticator is performed to observe that a notification is sent via an independent mechanism."
    },
    {
      "requirement_id": "KDH-013",
      "methods": [
        "Test"
      ],
      "rationale": "The system is tested by submitting a confirmation code twice to observe that the second submission is rejected."
    },
    {
      "requirement_id": "KDH-014",
      "methods": [
        "Test"
      ],
      "rationale": "The system is tested with an assertion signed by an incorrect key to observe that it is rejected, verifying signature validation."
    },
    {
      "requirement_id": "KDH-015",
      "methods": [
        "Test"
      ],
      "rationale": "The system is tested by submitting the same assertion twice to observe that the second submission is rejected."
    },
    {
      "requirement_id": "KDH-016",
      "methods": [
        "İnceleme"
      ],
      "rationale": "The federation transaction flow is inspected to verify that VBP initiates the transaction as the RP."
    },
    {
      "requirement_id": "KDH-017",
      "methods": [
        "Test"
      ],
      "rationale": "The proofing flow is executed with incorrect self-asserted information to observe that the error message does not reveal whether the information matches authoritative sources."
    },
    {
      "requirement_id": "KDH-018",
      "methods": [
        "Test"
      ],
      "rationale": "The IAL2 proofing process is executed with various core attributes to observe that they are validated against authoritative sources or via digital signatures."
    },
    {
      "requirement_id": "KDH-019",
      "methods": [
        "Test"
      ],
      "rationale": "The IAL2 proofing process is completed to observe that a notification is sent to the validated address."
    },
    {
      "requirement_id": "KDH-020",
      "methods": [
        "İnceleme"
      ],
      "rationale": "The system configuration and code are inspected to verify that knowledge-based verification is not implemented for identity verification."
    },
    {
      "requirement_id": "KDH-021",
      "methods": [
        "İnceleme"
      ],
      "rationale": "The system configuration and code are inspected to verify that email is not used for out-of-band authentication."
    },
    {
      "requirement_id": "KDH-022",
      "methods": [
        "Test"
      ],
      "rationale": "The system is tested by submitting an SMS code after 5 minutes to observe that it is rejected, and before 5 minutes to observe that it is accepted."
    },
    {
      "requirement_id": "KDH-023",
      "methods": [
        "Test"
      ],
      "rationale": "The system is tested by submitting the same SMS code twice to observe that the second submission is rejected."
    },
    {
      "requirement_id": "KDH-024",
      "methods": [
        "Test"
      ],
      "rationale": "The system is tested by generating a new SMS code after failed attempts to observe that the failed authentication count is not reset."
    },
    {
      "requirement_id": "KDH-025",
      "methods": [
        "Test"
      ],
      "rationale": "The system is tested by setting passwords that do not meet common composition requirements (e.g., no special characters) to observe that they are accepted."
    }
  ]
}

{
  "decisions": [
    {
      "requirement_id": "KDH-051",
      "methods": [
        "Test"
      ],
      "rationale": "HttpOnly attribute and Set-Cookie header usage are verified by executing the system and inspecting the network traffic or browser cookie store."
    },
    {
      "requirement_id": "KDH-052",
      "methods": [
        "Test"
      ],
      "rationale": "The presence and values of the Strict-Transport-Security header are verified by sending requests to the system and analyzing the response headers."
    },
    {
      "requirement_id": "KDH-053",
      "methods": [
        "Test"
      ],
      "rationale": "File upload validation is verified by submitting files with mismatched extensions and contents to observe the system's rejection behavior."
    },
    {
      "requirement_id": "KDH-054",
      "methods": [
        "Test"
      ],
      "rationale": "Image size limits are verified by uploading images with pixel dimensions exceeding the defined maximum to confirm rejection."
    },
    {
      "requirement_id": "KDH-055",
      "methods": [
        "Test"
      ],
      "rationale": "User enumeration prevention is verified by comparing error messages, HTTP codes, and response times for valid and invalid user identifiers during sign-in attempts."
    },
    {
      "requirement_id": "KDH-056",
      "methods": [
        "Test"
      ],
      "rationale": "Role-based access control for password reset is verified by attempting to initiate and complete password changes using Help Desk credentials."
    },
    {
      "requirement_id": "KDH-057",
      "methods": [
        "Test"
      ],
      "rationale": "Session token regeneration is verified by authenticating a user and checking that the previous token is invalidated and a new one is issued."
    },
    {
      "requirement_id": "KDH-058",
      "methods": [
        "Test"
      ],
      "rationale": "Session invalidation is verified by logging out or expiring a session and then attempting to use the old session token to access protected resources."
    },
    {
      "requirement_id": "KDH-059",
      "methods": [
        "Test"
      ],
      "rationale": "Re-authentication requirement for sensitive changes is verified by attempting to change account settings after the 5-minute window has elapsed without re-authenticating."
    },
    {
      "requirement_id": "KDH-060",
      "methods": [
        "Test"
      ],
      "rationale": "Access control is verified by attempting to access resources belonging to other users by modifying identifiers in the request."
    },
    {
      "requirement_id": "KDH-061",
      "methods": [
        "İnceleme"
      ],
      "rationale": "Text alternatives for non-text content are verified by inspecting the HTML markup and using accessibility tools to check for alt attributes and ARIA labels."
    },
    {
      "requirement_id": "KDH-062",
      "methods": [
        "İnceleme"
      ],
      "rationale": "Programmatic determination of structure and relationships is verified by inspecting the HTML source code for semantic elements and ARIA roles."
    },
    {
      "requirement_id": "KDH-063",
      "methods": [
        "Gösterim"
      ],
      "rationale": "Orientation independence is verified by rotating the device or resizing the window to ensure the content remains usable in both portrait and landscape modes."
    },
    {
      "requirement_id": "KDH-064",
      "methods": [
        "İnceleme"
      ],
      "rationale": "Form field purposes are verified by inspecting the HTML source code for appropriate autocomplete attributes on input fields."
    },
    {
      "requirement_id": "KDH-065",
      "methods": [
        "Analiz"
      ],
      "rationale": "Contrast ratios are verified by using automated accessibility tools or manual calculation to measure the color contrast between text and background."
    },
    {
      "requirement_id": "KDH-066",
      "methods": [
        "Gösterim"
      ],
      "rationale": "Text resizing is verified by zooming the browser to 200% and observing that the content remains readable and functional without loss of information."
    },
    {
      "requirement_id": "KDH-067",
      "methods": [
        "İnceleme"
      ],
      "rationale": "Use of text instead of images of text is verified by inspecting the HTML source code to ensure information is conveyed via text elements rather than images."
    },
    {
      "requirement_id": "KDH-068",
      "methods": [
        "Gösterim"
      ],
      "rationale": "Spacing adjustments are verified by applying CSS overrides to increase line height, paragraph spacing, and letter spacing to check for content loss."
    },
    {
      "requirement_id": "KDH-069",
      "methods": [
        "Test"
      ],
      "rationale": "Keyboard accessibility is verified by navigating and interacting with all functions using only the keyboard without relying on mouse or touch."
    },
    {
      "requirement_id": "KDH-070",
      "methods": [
        "Test"
      ],
      "rationale": "Session timeout warning and extension are verified by waiting for the 25-minute mark to observe the dialog, screen reader announcement, and extension functionality."
    },
    {
      "requirement_id": "KDH-071",
      "methods": [
        "İnceleme"
      ],
      "rationale": "Page titles are verified by inspecting the HTML source code to ensure each page has a descriptive <title> element."
    },
    {
      "requirement_id": "KDH-072",
      "methods": [
        "İnceleme"
      ],
      "rationale": "Link purpose clarity is verified by inspecting the HTML source code to ensure links have descriptive text or appropriate ARIA labels."
    },
    {
      "requirement_id": "KDH-073",
      "methods": [
        "Gösterim"
      ],
      "rationale": "Keyboard focus visibility is verified by navigating through the interface with the keyboard and observing that the focus indicator is clearly visible."
    },
    {
      "requirement_id": "KDH-074",
      "methods": [
        "İnceleme"
      ],
      "rationale": "Page language is verified by inspecting the HTML source code to ensure the <html> tag has a correct lang attribute."
    },
    {
      "requirement_id": "KDH-075",
      "methods": [
        "İnceleme"
      ],
      "rationale": "Language of sections is verified by inspecting the HTML source code to ensure elements with different languages have appropriate lang attributes."
    }
  ]
}

{
  "decisions": [
    {
      "requirement_id": "KDH-101",
      "methods": [
        "Test"
      ],
      "rationale": "Hareketsizlik kilidi ve FIDO2/PIN ile yeniden kimlik doğrulama akışının, sistem çalıştırılarak ve girdi verilerek gözlemlenmesi gerekir."
    },
    {
      "requirement_id": "KDH-102",
      "methods": [
        "Test"
      ],
      "rationale": "Oturumun belirlenen koşullarda otomatik olarak sonlandırılıp sonlandırılmadığı, sistem çalıştırılarak ve süreler beklenerek test edilmelidir."
    },
    {
      "requirement_id": "KDH-103",
      "methods": [
        "Test"
      ],
      "rationale": "Denetim kayıtlarının gerekli alanları (tür, zaman, yer, kaynak, sonuç, kimlik) içerip içermediği, olaylar tetiklenerek ve kayıtlar incelenerek test edilmelidir."
    },
    {
      "requirement_id": "KDH-104",
      "methods": [
        "Test"
      ],
      "rationale": "Zaman damgalarının UTC cinsinden ve doğru ayrıntı düzeyinde kaydedilip kaydedilmediği, sistem çalıştırılarak ve kayıtlar kontrol edilerek test edilmelidir."
    },
    {
      "requirement_id": "KDH-105",
      "methods": [
        "Test"
      ],
      "rationale": "Yetkisiz erişim, değişiklik veya silme girişimlerinin algılanıp algılanmadığı ve uyarıların gönderilip gönderilmediği, saldırı senaryoları çalıştırılarak test edilmelidir."
    },
    {
      "requirement_id": "KDH-106",
      "methods": [
        "Gösterim"
      ],
      "rationale": "Parola ve tek kullanımlık kodların ekranda gizlenip gizlenmediği, arayüzün çalıştırılıp gözlemlenmesiyle gösterilebilir."
    },
    {
      "requirement_id": "KDH-107",
      "methods": [
        "Test"
      ],
      "rationale": "Hassas işlemler öncesi tazelik süresi dolunca yeniden kimlik doğrulama zorunluluğunun uygulanıp uygulanmadığı, sistem çalıştırılarak test edilmelidir."
    },
    {
      "requirement_id": "KDH-108",
      "methods": [
        "Analiz"
      ],
      "rationale": "İletişim kanallarının şifreleme ve bütünlük korumasının (SC-8) uygunluğu, protokol analizi veya güvenlik modeli incelemesi gerektirir."
    },
    {
      "requirement_id": "KDH-109",
      "methods": [
        "Test"
      ],
      "rationale": "Geçersiz girdilerin (bozuk veri, aşırı boyut vb.) reddedilip reddedilmediği, çeşitli girdilerle sistem çalıştırılarak test edilmelidir."
    },
    {
      "requirement_id": "KDH-110",
      "methods": [
        "Test"
      ],
      "rationale": "Hata mesajlarının kullanıcıya genel bilgi verip vermediği ve ayrıntılı logların yetkili personele gösterilip gösterilmediği, hata senaryoları çalıştırılarak test edilmelidir."
    },
    {
      "requirement_id": "KDH-111",
      "methods": [
        "Test"
      ],
      "rationale": "Oturum süresi uzatılmaması, uyarı gösterilmesi, taslak kaydı ve veri kaybı olmadan devam etme akışının, sistem çalıştırılarak test edilmesi gerekir."
    },
    {
      "requirement_id": "KDH-112",
      "methods": [
        "Test"
      ],
      "rationale": "CAPTCHA kullanılmaması ve bot eşiği aşıldığında etkileşimsiz kanıt veya WCAG uyumlu sorgunun gösterilip gösterilmediği, senaryolar çalıştırılarak test edilmelidir."
    },
    {
      "requirement_id": "KDH-113",
      "methods": [
        "Test"
      ],
      "rationale": "Ödeme sonucunun yalnızca imzalı bildirimle kabul edilmesi ve belirsiz durumlarda 'ödeme bekliyor' durumunda tutulması, simüle edilmiş KÖA yanıtlarıyla test edilmelidir."
    },
    {
      "requirement_id": "KDH-114",
      "methods": [
        "Test"
      ],
      "rationale": "AAL2 altı veya eksik alan içeren e-Devlet belirteçlerinde oturumun sınırlı kipte açılıp açılmadığı, farklı belirteçlerle test edilmelidir."
    },
    {
      "requirement_id": "KDH-115",
      "methods": [
        "Test"
      ],
      "rationale": "Parola geçerlilik süresinin yalnızca şirket temsilcilerine uygulanması, bildirim gönderilmesi ve ele geçirme kanıtında zorunlu değişiklik, senaryolarla test edilmelidir."
    },
    {
      "requirement_id": "KDH-116",
      "methods": [
        "Test"
      ],
      "rationale": "TOTP kodlarının yalnızca geçerli ve bir önceki adımda kabul edilmesi, eski/ileri adımların reddedilmesi ve tek kullanımlık olması, zamanlanmış testlerle doğrulanmalıdır."
    },
    {
      "requirement_id": "KDH-117",
      "methods": [
        "Test"
      ],
      "rationale": "Başarısız deneme eşiği aşıldığında doğrulayıcının devre dışı bırakılması, hesap kurtarma gerekliliği ve sayaç sıfırlama, tekrarlı başarısız girişlerle test edilmelidir."
    },
    {
      "requirement_id": "KDH-118",
      "methods": [
        "Test"
      ],
      "rationale": "AAL2 ve AAL3 oturumlarında hareketsizlik sonrası farklı davranışların (parola ile devam, e-Devlet yönlendirme, oturum sırrı silme) uygulanıp uygulanmadığı, senaryolarla test edilmelidir."
    },
    {
      "requirement_id": "KDH-119",
      "methods": [
        "Test"
      ],
      "rationale": "Eşzamanlı oturum sınırının aşılması durumunda en eski oturumun sonlandırılması, kullanıcıya bildirim ve SIEM'e olay iletimi, çoklu oturum açma testleriyle doğrulanmalıdır."
    },
    {
      "requirement_id": "KDH-120",
      "methods": [
        "Test"
      ],
      "rationale": "Dosya türü, içerik imzası ve boyut/sayı sınırlarının denetlenmesi ile ret mesajlarının içeriği, çeşitli dosya yüklemeleriyle test edilmelidir."
    }
  ]
}

{
  "decisions": [
    {
      "requirement_id": "ETC-076",
      "methods": [
        "Test"
      ],
      "rationale": "The behavior of ignoring infill information after reading a balise group or detecting a miss is a dynamic system response that must be observed by simulating the sequence of events and inputs."
    },
    {
      "requirement_id": "ETC-077",
      "methods": [
        "Test"
      ],
      "rationale": "Verifying that the OBU ignores session orders when GSM-R is not installed requires configuring the system in that state and observing the response to a simulated order."
    },
    {
      "requirement_id": "ETC-078",
      "methods": [
        "Test"
      ],
      "rationale": "The process of terminating an existing session and establishing a new one upon reaching a specific location is a dynamic operational sequence that must be executed and observed."
    },
    {
      "requirement_id": "ETC-079",
      "methods": [
        "Test"
      ],
      "rationale": "The OBU's decision to ignore an order in a degraded single-session situation is a conditional behavior that must be verified by simulating the degraded state and the incoming order."
    },
    {
      "requirement_id": "ETC-080",
      "methods": [
        "Test"
      ],
      "rationale": "The timing and triggering of information transmission to the RIU based on location and balise events are dynamic behaviors that require execution and observation of the output."
    },
    {
      "requirement_id": "ETC-081",
      "methods": [
        "Test"
      ],
      "rationale": "Verifying the content of the data sent to the RIU requires capturing the transmitted message during a test run and checking for the presence of the specified fields."
    },
    {
      "requirement_id": "ETC-082",
      "methods": [
        "Test"
      ],
      "rationale": "The consistency check of received data is a functional behavior that can be verified by injecting valid and invalid data and observing the OBU's acceptance or rejection."
    },
    {
      "requirement_id": "ETC-083",
      "methods": [
        "Test"
      ],
      "rationale": "The action of ignoring further infill information after a specific event is a dynamic state transition that must be observed by simulating the event and subsequent data reception."
    },
    {
      "requirement_id": "ETC-084",
      "methods": [
        "Test"
      ],
      "rationale": "Terminating a session based on trackside orders or level changes is a dynamic response to external inputs that must be verified by executing the scenarios."
    },
    {
      "requirement_id": "ETC-085",
      "methods": [
        "Test"
      ],
      "rationale": "The generation of an acknowledgement message with a specific ID in response to an emergency message is a functional output that must be observed during a test."
    },
    {
      "requirement_id": "ETC-086",
      "methods": [
        "Test"
      ],
      "rationale": "The rejection of new movement authorities while an emergency stop is active is a conditional behavior that must be verified by simulating the emergency state and sending a new MA."
    },
    {
      "requirement_id": "ETC-087",
      "methods": [
        "Test"
      ],
      "rationale": "The acknowledgement of revocation messages is a functional response that must be observed by sending a revocation and checking the OBU's output."
    },
    {
      "requirement_id": "ETC-088",
      "methods": [
        "Test"
      ],
      "rationale": "The persistence and replacement of speed restrictions, including across level changes, is a complex state management behavior that must be verified through a sequence of test cases."
    },
    {
      "requirement_id": "ETC-089",
      "methods": [
        "Test"
      ],
      "rationale": "The priority logic for applying trackside speed limits over national and default values is a functional decision that must be verified by providing conflicting inputs and observing the applied limit."
    },
    {
      "requirement_id": "ETC-090",
      "methods": [
        "Test"
      ],
      "rationale": "Verifying that the maximum train speed is handled as a specific category of static speed restriction requires configuring the train data and observing how the OBU processes this value in its speed supervision logic."
    },
    {
      "requirement_id": "ETC-091",
      "methods": [
        "Test"
      ],
      "rationale": "The computation and recomputation of speed restrictions based on input changes is a functional behavior that can be verified by changing inputs and observing the resulting speed limit."
    },
    {
      "requirement_id": "ETC-092",
      "methods": [
