{
  "test_cases": [
    {
      "id": "TC-001",
      "title": "OBU acknowledges revocation of emergency message",
      "covers": [
        "ETC-087"
      ],
      "type": "Normal",
      "priority": "Yüksek",
      "preconditions": "OBU is in a mode where it can receive radio messages (e.g., FSD or OS). An emergency message with a specific identifier (NID_EM) has been previously received and acknowledged by the OBU.",
      "test_inputs": "A revocation message (Message 18) containing the NID_EM of the previously received emergency message and M_ACK set to 1.",
      "assumptions": "The radio link is stable and allows for message transmission and reception.",
      "steps": [
        {
          "no": 1,
          "action": "Send a revocation message (Message 18) from the RBC to the OBU. The message must contain the NID_EM of the active emergency message and the M_ACK field set to 1 (acknowledgement requested).",
          "expected": "The OBU receives the message and processes it. The emergency message associated with the NID_EM is revoked on the OBU."
        },
        {
          "no": 2,
          "action": "Monitor the uplink radio traffic from the OBU to the RBC.",
          "expected": "The OBU sends an acknowledgement message to the RBC. The acknowledgement message refers to the time stamp of the revocation message sent by the trackside, as per SUBSET-026 §3.16.3.5.3."
        }
      ]
    },
    {
      "id": "TC-002",
      "title": "OBU does not acknowledge inconsistent revocation message",
      "covers": [
        "ETC-087"
      ],
      "type": "Hata",
      "priority": "Orta",
      "preconditions": "OBU is in a mode where it can receive radio messages. No emergency message with the identifier NID_EM_X is currently active on the OBU.",
      "test_inputs": "A revocation message (Message 18) containing an NID_EM (NID_EM_X) that does not correspond to any active emergency message on the OBU, with M_ACK set to 1.",
      "assumptions": "The OBU validates the consistency of the revocation message against its internal state of emergency messages.",
      "steps": [
        {
          "no": 1,
          "action": "Send a revocation message (Message 18) from the RBC to the OBU with an NID_EM that is not currently active on the OBU. Set M_ACK to 1.",
          "expected": "The OBU identifies the message as inconsistent (referring to a non-existent or already revoked emergency message)."
        },
        {
          "no": 2,
          "action": "Monitor the uplink radio traffic from the OBU to the RBC for a period sufficient to cover the expected acknowledgement timeout.",
          "expected": "The OBU does not send an acknowledgement message for this specific revocation message, in accordance with SUBSET-026 §3.16.3.5.1 which states that acknowledgement is sent 'unless this message is considered as inconsistent'."
        }
      ]
    }
  ]
}

