        },
        {
          "no": 2,
          "action": "Observe the OBU's internal speed restriction state or output.",
          "expected": "The OBU computes and applies a non-zero speed restriction value (V_PBD) based on the received PBD data."
        }
      ]
    },
    {
      "id": "TC-091-02",
      "title": "Recomputation of PBD speed restriction only when inputs change",
      "covers": [
        "ETC-091"
      ],
      "type": "Normal",
      "priority": "Yüksek",
      "preconditions": "OBU has an active PBD speed restriction computed from a previous trackside message.",
      "test_inputs": "1. A new trackside profile message with identical PBD inputs (same PBD value, same gradient, same brake type, same locations). 2. A new trackside profile message with a changed PBD value.",
      "assumptions": "The OBU logs or exposes the calculation trigger status or allows observation of the calculation process.",
      "steps": [
        {
          "no": 1,
          "action": "Send a new trackside profile message with identical PBD inputs to the current active restriction.",
          "expected": "The OBU does not recompute the speed restriction. The existing restriction value remains unchanged."
        },
        {
          "no": 2,
          "action": "Send a new trackside profile message with a different PBD value (e.g., increased PBD).",
          "expected": "The OBU recomputes the speed restriction. The new restriction value reflects the updated PBD input."
        }
      ]
    },
